async function enableLocalExtension(id){const ext=state.extensions.find(x=>x.id===id),button=$(`[data-local-extension-confirm="${CSS.escape(id)}"]`);if(!ext)return;if(button){button.disabled=true;button.textContent='Descargando…'}try{const record=await window.HanamiLocalExtensions.download(ext,ext.externalStore);for(const source of record.sources){if(!state.sources.some(x=>x.id===source.id))state.sources.push({...source,extensionId:id,external:true});state.installed.add(source.id);state.disabled.delete(source.id)}persist();rebuildExtensionCatalog();renderExtensions();renderSources();$('#modal').close();toast('Extensión habilitada en el navegador')}catch(error){if(button){button.disabled=false;button.textContent='Reintentar'}const note=$('.local-extension-trust .notice');if(note){note.textContent=error.message;note.classList.add('error')}}}
function modal(html){$('#modalBody').innerHTML=html;$('#modal').showModal()}
function showBrowseChild(type,html,restoring=false,restore,data={}){['library','updates','history','groups','more','sources','extensions','migrate','globalSearch','browseChild'].forEach(x=>$('#'+x).classList.add('hidden'));$('#exploreChrome').classList.add('hidden');$('#exploreTabs').classList.add('hidden');$('#browser').classList.add('hidden');$('#hero').classList.add('hidden');$('#browseChild').classList.remove('hidden');$('#browseChildRoot').innerHTML=html;window.HanamiNavigation?.setChild(true);if(!restoring)window.HanamiScreens?.push(type,data,{restore:restore||(()=>{})})}
function browseChildHead(title,actions=''){return `<header class="destination-appbar browse-child-appbar"><button data-child-back aria-label="Atrás">←</button><h2>${esc(title)}</h2><span></span>${actions}</header>`}
function extensionInfo(id,restoring=false){const x=state.extensions.find(e=>e.id===id);if(!x)return;const ids=extensionSourceIds(x),installed=installedExtension(x),actions=`<button data-extension-details-repo="${esc(id)}" aria-label="Abrir repositorio">↗</button><button data-extension-details-more="${esc(id)}" aria-label="Más opciones">⋮</button>`;showBrowseChild('extension-details',browseChildHead('Información de extensión',actions)+`<section class="extension-details-page"><div class="extension-details-hero"><div class="row-avatar">${initials(x.name)}</div><div><h3>${esc(x.name)}</h3><p>${esc(x.description||'Adaptador de fuente para Hanami Web.')}</p></div></div><dl><div><dt>Versión</dt><dd>${esc(x.version||'1.0')}</dd></div><div><dt>Idioma</dt><dd>${esc(languageName(x.lang))}</dd></div><div><dt>Runtime</dt><dd>${esc(x.runtime||'vercel-js')}</dd></div><div><dt>Estado</dt><dd>${installed?'Instalada':'Disponible'}</dd></div></dl>${x.contentWarning?`<button class="browse-warning" data-extension-warning="${esc(id)}">⚠ Aviso de contenido</button>`:''}${installed?`<label class="browse-switch-row"><span><b>Modo incógnito</b><small>No registrar actividad de esta extensión</small></span><input type="checkbox" data-incognito-extension="${esc(id)}" ${state.incognito.has(id)?'checked':''}></label><h4>Fuentes</h4>${ids.map(sid=>{const src=sourceById(sid);return src?`<div class="extension-source-row"><button data-open-source="${esc(sid)}"><b>${esc(src.name)}</b><small>${esc(languageName(src.lang))}</small></button><button data-source-preferences="${esc(sid)}" aria-label="Ajustes">⚙</button><input type="checkbox" data-source-enabled="${esc(sid)}" ${state.disabled.has(sid)?'':'checked'}></div>`:''}).join('')}<button class="btn danger" data-extension-uninstall-dialog="${esc(id)}">Desinstalar</button>`:`<button class="btn acid" data-extension-install="${esc(id)}">Instalar / adjuntar</button>`}</section>`,restoring,()=>extensionInfo(id,true),{id})}
function sourceFilterDialog(restoring=false){const installed=state.sources.filter(x=>state.installed.has(x.id)),langs=[...new Set(installed.map(x=>x.lang))],enabled=state.sourceFilters.langsExplicit?state.sourceFilters.langs:langs;showBrowseChild('sources-filter',browseChildHead('Fuentes')+`<section class="browse-settings-list"><label class="browse-switch-row"><span><b>Solo ancladas</b><small>Mostrar únicamente fuentes fijadas</small></span><input type="checkbox" data-bc-source-pinned ${state.sourceFilters.onlyPinned?'checked':''}></label>${langs.map(l=>`<section class="browse-language-group"><label class="browse-switch-row"><span><b>${esc(languageName(l))}</b><small>Idioma de fuentes</small></span><input type="checkbox" data-bc-source-lang="${esc(l)}" ${enabled.includes(l)?'checked':''}></label>${enabled.includes(l)?installed.filter(x=>x.lang===l).map(x=>`<label class="browse-source-toggle"><span class="row-avatar">${initials(x.name)}</span><span><b>${esc(x.name)}</b><small>${esc(x.runtime||'web')}</small></span><input type="checkbox" data-bc-source-enabled="${esc(x.id)}" ${state.disabled.has(x.id)?'':'checked'}></label>`).join(''):''}</section>`).join('')}</section>`,restoring,()=>sourceFilterDialog(true))}
function extensionFilterDialog(restoring=false){const langs=[...new Set(state.extensions.map(x=>x.lang||'all'))],enabled=state.extensionFilters.langsExplicit?state.extensionFilters.langs:langs;showBrowseChild('extensions-filter',browseChildHead('Extensiones')+`<section class="browse-settings-list"><div class="browse-filter-chips">${[['all','Todas'],['installed','Instaladas'],['available','Disponibles']].map(([v,n])=>`<button class="${state.extensionFilters.status===v?'active':''}" data-bc-extension-status="${v}">${n}</button>`).join('')}</div>${langs.map(l=>`<label class="browse-switch-row"><span><b>${esc(languageName(l))}</b><small>Mostrar extensiones en este idioma</small></span><input type="checkbox" data-bc-extension-lang="${esc(l)}" ${enabled.includes(l)?'checked':''}></label>`).join('')}</section>`,restoring,()=>extensionFilterDialog(true))}
function globalSearchDialog(restoring=false){['library','updates','history','groups','more','sources','extensions','migrate','globalSearch','browseChild'].forEach(x=>$('#'+x).classList.add('hidden'));$('#exploreChrome').classList.add('hidden');$('#exploreTabs').classList.add('hidden');$('#browser').classList.add('hidden');$('#hero').classList.add('hidden');$('#globalSearch').classList.remove('hidden');window.HanamiNavigation?.setChild(true);if(!restoring)window.HanamiScreens?.push('global-search',{}, {restore:()=>globalSearchDialog(true)});const root=$('#globalSearchRoot');root.innerHTML=`<header class="global-search-toolbar"><div class="global-search-main"><button data-child-back aria-label="Atrás">←</button><input id="globalQuery" placeholder="Buscar en todas las fuentes…" aria-label="Búsqueda global"><button data-run-global aria-label="Buscar">⌕</button></div><progress id="globalProgress" class="global-search-progress hidden" max="1" value="0"></progress><nav class="global-search-chips"><button class="active" data-global-filter="all">✓ Todas</button><button data-global-filter="pinned">⌖ Ancladas</button><button data-global-results-only>≡ Con resultados</button></nav></header><div id="globalResults" class="global-search-results"><div class="global-search-empty">Escribe un título para buscar simultáneamente en las fuentes habilitadas.</div></div>`;root.querySelector('#globalQuery')?.focus()}
async function runGlobal(){const q=$('#globalQuery')?.value.trim(),out=$('#globalResults'),progress=$('#globalProgress');if(!q||!out)return;const mode=$('.global-search-chips [data-global-filter].active')?.dataset.globalFilter||'all',only=$('[data-global-results-only]')?.classList.contains('active'),sources=filteredSources().filter(s=>mode!=='pinned'||state.pinned.has(s.id));progress.max=Math.max(1,sources.length);progress.value=0;progress.classList.toggle('hidden',!sources.length);out.innerHTML=sources.map(s=>`<section class="group" data-global-group="${esc(s.id)}"><button class="group-title" data-global-source="${esc(s.id)}">${esc(s.name)} · …</button><p class="global-search-loading">Buscando…</p></section>`).join('')||'<div class="global-search-empty">No hay fuentes disponibles.</div>';let done=0;await Promise.all(sources.map(async s=>{let items=[],error='';try{items=(await api(`/api/source/${encodeURIComponent(s.id)}/search?q=${encodeURIComponent(q)}`)).mangas||[]}catch(e){error=e.message}done++;progress.value=done;const group=$(`[data-global-group="${CSS.escape(s.id)}"]`);if(group){group.classList.toggle('hidden',only&&!items.length);group.innerHTML=`<button class="group-title" data-global-source="${esc(s.id)}">${esc(s.name)} · ${items.length}</button>${error?`<p class="error">${esc(error)}</p>`:items.length?`<div class="cards">${items.slice(0,12).map(m=>`<button class="card" data-global-open="${esc(s.id)}" data-global-url="${esc(m.url)}"><img src="${esc(m.thumbnailUrl||'/assets/fallen.webp')}" alt=""><div><b>${esc(m.title)}</b></div></button>`).join('')}</div>`:'<p class="empty">Sin resultados.</p>'}`}}));setTimeout(()=>progress.classList.add('hidden'),350)}
function libraryBySource(){return Object.groupBy(state.library.filter(x=>x.favorite!==false),x=>x.sourceId)}
function migrationSources(){const counts=libraryBySource();let list=state.sources.filter(s=>(counts[s.id]||[]).length).map(s=>({s,count:counts[s.id].length}));list.sort((a,b)=>state.sortMode==='count'?a.count-b.count:a.s.name.localeCompare(b.s.name));if(state.sortDir==='desc')list.reverse();return list}
function renderMigration(){if(state.migrateSource)return renderMigrationItems();const list=migrationSources();$('#migrationView').innerHTML=list.length?`<p class="mono">Selecciona una fuente para ver sus objetos.</p>${list.map(({s,count})=>`<button class="row migrate-source" data-migrate-source="${esc(s.id)}" style="width:100%;color:inherit;text-align:left"><div class="row-avatar">${initials(s.name)}</div><div class="row-main"><b>${esc(s.name)}</b><small>${esc(languageName(s.lang))}</small></div><span class="count">${count}</span></button>`).join('')}`:'<p class="empty">La biblioteca está vacía. Abre una obra y pulsa “＋ Biblioteca”.</p>'}
function renderMigrationItems(restoring=false){const src=sourceById(state.migrateSource);if(!src)return;const items=state.library.filter(x=>x.favorite!==false&&String(x.sourceId)===String(src.id)).sort((a,b)=>a.title.localeCompare(b.title));showBrowseChild('migrate-manga',browseChildHead(src.name)+`<section class="migrate-manga-screen">${items.length?`<div class="migrate-manga-list">${items.map(x=>`<label class="migrate-manga-row"><button data-migrate-cover="${esc(x.id)}"><img src="${esc(x.thumbnailUrl||'/assets/fallen.webp')}" alt=""></button><span><b>${esc(x.title)}</b><small>${esc(x.url||'')}</small></span><input type="checkbox" data-migrate-item="${esc(x.id)}"></label>`).join('')}</div><button class="migrate-continue-fab" data-migrate-continue disabled>Continuar <span id="migrationSelectionCount">0</span> →</button>`:'<p class="empty">No hay obras en esta fuente.</p>'}</section>`,restoring,()=>renderMigrationItems(true),{sourceId:src.id})}
async function findMigrations(){const target=$('#migrationTarget').value,selected=$$('[data-migrate-item]:checked').map(x=>state.library.find(y=>y.id===x.dataset.migrateItem)).filter(Boolean),out=$('#migrationResults');out.innerHTML='<p class="empty">Buscando coincidencias…</p>';const results=await Promise.all(selected.map(async item=>{try{return{item,matches:(await api(`/api/source/${encodeURIComponent(target)}/search?q=${encodeURIComponent(item.title)}`)).mangas||[]}}catch(e){return{item,matches:[],error:e.message}}}));out.innerHTML=`<h3>Coincidencias</h3>${results.map(({item,matches,error})=>`<div class="migration-result"><div><b>${esc(item.title)}</b><small class="mono">${error?esc(error):matches.length?`→ ${esc(matches[0].title)}`:'Sin coincidencias'}</small></div>${matches.length?`<button class="btn acid" data-accept-migration="${esc(item.id)}" data-target="${esc(target)}" data-match='${esc(JSON.stringify(matches[0]))}'>Migrar</button>`:''}</div>`).join('')}`}
function acceptMigration(btn){const item=state.library.find(x=>x.id===btn.dataset.acceptMigration),match=JSON.parse(btn.dataset.match),old={...item};item.sourceId=btn.dataset.target;item.title=match.title;item.url=match.url;item.thumbnailUrl=match.thumbnailUrl||item.thumbnailUrl;window.HanamiNotes?.move(old,old.sourceId,item,item.sourceId);item.notes=old.notes||window.HanamiNotes?.get(item,item.sourceId)||'';state.migrations.push({at:Date.now(),from:old,to:{...item}});persist();btn.textContent='Migrado';btn.disabled=true;toast('Migración guardada')}
async function init(){try{const[s,e]=await Promise.all([api('/api/sources'),api('/api/extensions')]);await window.HanamiLocalExtensions?.ready;const localSource=window.HanamiLocalSource?.manifest;state.sources=[...(localSource?[localSource]:[]),...s.filter(source=>source.id!==localSource?.id),...(window.HanamiLocalExtensions?.sources?.()||[]).filter(local=>!s.some(source=>source.id===local.id)&&local.id!==localSource?.id)];if(localSource)state.installed.add(localSource.id);(window.HanamiLocalExtensions?.sources?.()||[]).forEach(source=>state.installed.add(source.id));store.set('hanami-source-registry',state.sources);state.library.forEach(x=>x.title=cleanWorkTitle(x.title,x.sourceId));persist();state.builtinExtensions=(e.items||[]).map(x=>({...x,sourceIds:x.sourceIds||[x.id]}));const removedStores=purgeIncompatibleExtensionStores();rebuildExtensionCatalog();if(!store.get('hanami-install-seeded',false)){state.sources.forEach(x=>state.installed.add(x.id));store.set('hanami-install-seeded',true);persist()}$('#apiState').textContent='● VERCEL ONLINE';renderSources();if(!window.HanamiScreens?.needsRestore?.())showTab('library','replace');if(removedStores){persist();toast(`${removedStores} repositorio(s) incompatible(s) eliminado(s)`)}setTimeout(handleExtensionStoreDeepLink,0)}catch(e){$('#apiState').textContent='● API OFFLINE';$('#sourceGroups').innerHTML=`<p class="error">${esc(e.message)}</p>`}finally{document.documentElement.dataset.hanamiReady='true';dispatchEvent(new CustomEvent('hanami-app-ready'))}}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-migrate-item]');if(!b)return;if(b.dataset.tab){if(b.dataset.tab==='library'&&window.HanamiNavigation?.isActive?.('library'))window.HanamiLibrary?.openSettings?.();else if(b.dataset.tab==='explore'&&window.HanamiNavigation?.isActive?.('explore'))window.HanamiBrowseTab?.onReselect?.();else if(b.dataset.tab==='updates'&&window.HanamiNavigation?.isActive?.('updates'))window.HanamiUpdatesTab?.onReselect?.();else if(b.dataset.tab==='history'&&window.HanamiNavigation?.isActive?.('history'))window.HanamiHistoryTab?.onReselect?.();else if(b.dataset.tab==='groups'&&window.HanamiNavigation?.isActive?.('groups'))window.HanamiReadingGroups?.render();else if(b.dataset.tab==='more'&&window.HanamiNavigation?.isActive?.('more'))window.HanamiMoreTab?.onReselect?.();else showTab(b.dataset.tab,'push')};if(b.dataset.exploreTab)showTab(b.dataset.exploreTab,'push');if(b.hasAttribute('data-home'))showTab('explore','push');if(b.dataset.openSource)openSource(b.dataset.openSource);if(b.dataset.latestSource)openSource(b.dataset.latestSource,'latest');if(b.dataset.pinSource){state.pinned.has(b.dataset.pinSource)?state.pinned.delete(b.dataset.pinSource):state.pinned.add(b.dataset.pinSource);persist();renderSources()}if(b.hasAttribute('data-source-filter'))sourceFilterDialog();if(b.hasAttribute('data-global-search'))globalSearchDialog();if(b.hasAttribute('data-run-global'))runGlobal();if(b.dataset.globalFilter){$$('[data-global-filter]').forEach(x=>x.classList.toggle('active',x===b))}if(b.hasAttribute('data-global-results-only')){b.classList.toggle('active');$$('[data-global-group]').forEach(x=>x.classList.toggle('hidden',b.classList.contains('active')&&!x.querySelector('.card')))}if(b.hasAttribute('data-close-browser'))window.HanamiScreens?window.HanamiScreens.back():showTab('sources');if(b.hasAttribute('data-browse-display'))browseDisplayMenu(b);if(b.hasAttribute('data-browse-source-more'))browseSourceMenu(b);if(b.dataset.browseDisplayMode){store.set('hanami-browse-display',b.dataset.browseDisplayMode);window.HanamiOverlays?.close?.();setTimeout(()=>browse(state.browseMode||'popular',state.browseQuery||''),0)}if(b.hasAttribute('data-browse-open-web')){window.HanamiOverlays?.close?.();window.open(state.activeSource?.baseUrl||'https://olympusxyz.com','_blank','noopener')}if(b.hasAttribute('data-browse-source-settings')){window.HanamiOverlays?.close?.();setTimeout(()=>modal(`<div class="dialog-section"><small class="eyebrow">FUENTE</small><h3>${esc(state.activeSource?.name||'Ajustes')}</h3><p>Este adaptador web no expone preferencias adicionales.</p></div>`),0)}if(b.hasAttribute('data-source-popular'))browse('popular');if(b.hasAttribute('data-source-latest'))browse('latest');if(b.hasAttribute('data-source-search'))browse('search',$('#sourceQuery').value.trim());if(b.dataset.manga!=null)openManga(+b.dataset.manga);if(b.dataset.chapter!=null)openChapter(+b.dataset.chapter);if(b.hasAttribute('data-library-current')||b.hasAttribute('data-add-current'))addCurrentToLibrary();if(b.hasAttribute('data-close-reader')){$('#reader').classList.add('hidden');document.body.style.overflow=''}if(b.hasAttribute('data-extension-search'))$('#extensionSearchBox').classList.remove('hidden');if(b.hasAttribute('data-close-extension-search')){$('#extensionSearchBox').classList.add('hidden');$('#extensionQuery').value='';renderExtensions()}if(b.hasAttribute('data-extension-menu'))$('#extensionMenu').classList.toggle('hidden');if(b.hasAttribute('data-extension-filter'))closeExtensionMenuThen(()=>extensionFilterDialog());if(b.hasAttribute('data-toggle-extension-list'))closeExtensionMenuThen(()=>{state.extensionDetailed=!state.extensionDetailed;store.set('hanami-extension-list-detailed',state.extensionDetailed);renderExtensions()});if(b.dataset.extensionInfo)extensionInfo(b.dataset.extensionInfo);if(b.dataset.extensionInstall)toggleInstall(b.dataset.extensionInstall);if(b.hasAttribute('data-apply-source-filter')){state.sourceFilters.onlyPinned=$('[data-filter-pinned]').checked;state.sourceFilters.langs=$$('[data-filter-source-lang]:checked').map(x=>x.dataset.filterSourceLang);store.set('hanami-source-filters',state.sourceFilters);$('#modal').close();renderSources()}if(b.hasAttribute('data-apply-extension-filter')){state.extensionFilters.status=$('#extStatus').value;state.extensionFilters.langs=$$('[data-filter-extension-lang]:checked').map(x=>x.dataset.filterExtensionLang);store.set('hanami-extension-filters',state.extensionFilters);$('#modal').close();renderExtensions()}if(b.hasAttribute('data-sort-mode')){state.sortMode=state.sortMode==='alpha'?'count':'alpha';store.set('hanami-migrate-sort',state.sortMode);b.textContent=state.sortMode==='alpha'?'AZ':'#';renderMigration()}if(b.hasAttribute('data-sort-direction')){state.sortDir=state.sortDir==='asc'?'desc':'asc';store.set('hanami-migrate-direction',state.sortDir);b.textContent=state.sortDir==='asc'?'↓':'↑';renderMigration()}if(b.dataset.migrateSource){state.migrateSource=b.dataset.migrateSource;renderMigrationItems()}if(b.hasAttribute('data-migrate-back'))window.HanamiScreens?.back();if(b.hasAttribute('data-find-migrations'))findMigrations();if(b.dataset.acceptMigration)acceptMigration(b)});
$('#extensionQuery').addEventListener('input',renderExtensions);$('#sourceQuery').addEventListener('keydown',e=>{if(e.key==='Enter')browse('search',e.target.value.trim())});addEventListener('hanami-screen-restore',e=>{if(e.detail.type==='migration-candidate-detail')openSearchManga(e.detail.data.sourceId,e.detail.data.manga,true)});if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js');init();

