function browseOverflow(anchor,items,label){document.querySelectorAll('.browse-item-overflow').forEach(x=>x.remove());const n=document.createElement('div'),r=anchor.getBoundingClientRect(),w=Math.min(260,innerWidth-16);n.className='browse-item-overflow';n.setAttribute('role','menu');n.setAttribute('aria-label',label);n.style.width=w+'px';n.style.left=Math.max(8,Math.min(innerWidth-w-8,r.right-w))+'px';n.style.top=Math.min(innerHeight-items.length*46-12,r.bottom+4)+'px';n.innerHTML=items.map(x=>`<button role="menuitem" ${x.attr}>${esc(x.label)}</button>`).join('');document.body.append(n);window.HanamiOverlays?.scan?.()}
function browseDisplayMenu(anchor){const current=store.get('hanami-browse-display','comfortable');browseOverflow(anchor,[['comfortable','Cuadrícula cómoda'],['compact','Cuadrícula compacta'],['list','Lista']].map(([v,label])=>({label:(current===v?'✓ ':'')+label,attr:`data-browse-display-mode="${v}"`})),'Modo de visualización')}
function browseSourceMenu(anchor){browseOverflow(anchor,[{label:'Abrir en vista web',attr:'data-browse-open-web'},{label:'Ajustes de la fuente',attr:'data-browse-source-settings'}],'Opciones de fuente')}
function sourceOptionsDialog(id){const s=sourceById(id);if(!s)return;const pinned=state.pinned.has(id),local=id==='hanami.local';modal(`<div class="dialog-section"><small class="eyebrow">OPCIONES DE FUENTE</small><h3>${esc(s.name)}</h3><button class="filter-option action-row" data-option-pin="${esc(id)}">${pinned?'Desanclar':'Anclar'} fuente</button><button class="filter-option action-row" data-option-latest="${esc(id)}">Abrir recientes</button>${local?'<button class="filter-option action-row" data-local-create>Crear serie</button><button class="filter-option action-row" data-local-import>Importar ZIP</button><button class="filter-option action-row" data-local-manage>Gestionar series</button><button class="filter-option action-row" data-local-help>Ayuda de formato</button>':`<button class="filter-option action-row" data-option-web="${esc(id)}">Abrir sitio web</button><button class="filter-option action-row danger" data-option-disable="${esc(id)}">Deshabilitar fuente</button>`}</div>`)}
function closeExtensionMenuThen(action){const menu=$('#extensionMenu');if(!menu||menu.classList.contains('hidden'))return action();if(window.HanamiOverlays?.current?.()===menu){addEventListener('hanami-overlay-close',()=>setTimeout(action,0),{once:true});window.HanamiOverlays.close()}else{menu.classList.add('hidden');setTimeout(action,0)}}
function extensionStoresDialog(restoring=false){const actions='<button data-extension-stores-refresh aria-label="Actualizar repositorios" title="Actualizar repositorios"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 6v5h-5"></path><path d="M4 18v-5h5"></path><path d="M6.1 8A7 7 0 0 1 18 6l2 2"></path><path d="M17.9 16A7 7 0 0 1 6 18l-2-2"></path></svg></button>';const cards=state.extensionStores.map((x,i)=>`<article class="extension-store-card" data-extension-store-card="${i}" data-extension-store-url="${esc(x.indexUrl)}"><header><div class="row-avatar">${initials(x.name)}</div><div><b>${esc(x.name)}</b><small>${esc(x.badgeLabel||'GITHUB')} · ${x.extensionCount||0} extensión(es) · ${x.compatibleCount||0} web</small></div></header><p>${esc(x.indexUrl)}</p><footer><button data-extension-store-website="${i}" aria-label="Abrir web" title="Abrir web"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8"></circle><path d="M4 12h16M12 4c2.5 2.3 3.5 5 3.5 8s-1 5.7-3.5 8M12 4c-2.5 2.3-3.5 5-3.5 8s1 5.7 3.5 8"></path></svg></button>${x.discord?`<button data-extension-store-discord="${i}" aria-label="Abrir Discord" title="Abrir Discord">D</button>`:''}<button data-extension-store-copy="${i}" aria-label="Copiar URL" title="Copiar URL"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="8" y="8" width="11" height="11" rx="1"></rect><path d="M16 8V5H5v11h3"></path></svg></button><button class="danger" data-extension-store-delete="${i}" aria-label="Eliminar" title="Eliminar"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 7h14M9 7V4h6v3M8 10v8M12 10v8M16 10v8M7 7l1 13h8l1-13"></path></svg></button></footer></article>`).join('');showBrowseChild('extension-stores',browseChildHead('Repositorios de extensiones',actions)+`<section class="extension-stores-page"><p class="notice">Solo se aceptan extensiones Hanami vercel-js. Al habilitarlas, el bundle se guarda localmente y se ejecuta aislado en un Web Worker; nunca se admiten APK.</p><article class="extension-store-card bundled"><header><div class="row-avatar">H</div><div><b>Hanami bundled registry</b><small>${state.builtinExtensions.length} adaptador(es) web · ACTIVO</small></div></header><p>Registro incluido en este proyecto Vercel.</p></article><div class="extension-store-list">${cards||'<div class="browse-empty-state compact"><b>No hay repositorios externos</b><span>Añade uno mediante una URL HTTPS de GitHub.</span></div>'}</div><button class="extension-store-fab" data-extension-store-create aria-label="Añadir repositorio"><span>＋</span> Añadir</button></section>`,restoring,()=>extensionStoresDialog(true))}
function extensionStoreConfirmDialog(url){modal(`<div class="extension-store-dialog"><h3>Añadir repositorio</h3><p>¿Quieres añadir este repositorio de extensiones?</p><label>URL de GitHub<input type="url" data-extension-store-url-input value="${esc(url)}" readonly></label><small data-extension-store-error></small><div><button data-extension-store-cancel>Cancelar</button><button class="acid" data-extension-store-confirm>Añadir</button></div></div>`)}
function extensionStoreCreateDialog(){modal(`<div class="extension-store-dialog"><h3>Añadir repositorio</h3><label>URL de GitHub<input type="url" inputmode="url" autocomplete="url" data-extension-store-url-input placeholder="https://github.com/propietario/repositorio" required></label><small data-extension-store-error>Obligatorio. El repositorio debe declarar bundles Hanami autocontenidos, fuentes y hosts HTTPS.</small><div><button data-extension-store-cancel>Cancelar</button><button class="acid" data-extension-store-confirm>Añadir</button></div></div>`);setTimeout(()=> $('[data-extension-store-url-input]')?.focus(),0)}
async function addExtensionStore(){const input=$('[data-extension-store-url-input]'),error=$('[data-extension-store-error]'),button=$('[data-extension-store-confirm]'),url=input?.value.trim();if(!url){error.textContent='La URL es obligatoria';error.classList.add('error-text');return}if(state.extensionStores.some(x=>x.inputUrl===url||x.indexUrl===url)){error.textContent='Este repositorio ya existe';error.classList.add('error-text');return}button.disabled=true;button.textContent='Procesando…';try{const item=await api('/api/extension-store/inspect',{method:'POST',body:JSON.stringify({url})});if(state.extensionStores.some(x=>x.indexUrl===item.indexUrl))throw new Error('Este repositorio ya existe');state.extensionStores.push(item);persist();rebuildExtensionCatalog();renderExtensions();$('#modal').close();extensionStoresDialog(true);toast('Repositorio añadido')}catch(e){error.textContent=e.message;error.classList.add('error-text');button.disabled=false;button.textContent='Añadir'}}
function deleteExtensionStore(index){const item=state.extensionStores[index];if(!item)return;modal(`<div class="extension-store-dialog"><h3>Eliminar repositorio</h3><p>Se eliminará <b>${esc(item.name)}</b>.</p><small>${esc(item.indexUrl)}</small><div><button data-extension-store-cancel>Cancelar</button><button class="danger" data-extension-store-delete-confirm="${index}">Eliminar</button></div></div>`)}
async function confirmDeleteExtensionStore(index){const item=state.extensionStores[index];for(const ext of item?.adapters||[])if((window.HanamiLocalExtensions?.records?.()||[]).some(x=>x.id===ext.id)){await window.HanamiLocalExtensions.disable(ext.id);state.sources=state.sources.filter(source=>!ext.sourceIds.includes(source.id));ext.sourceIds.forEach(id=>state.installed.delete(id))}state.extensionStores.splice(index,1);persist();rebuildExtensionCatalog();renderExtensions();renderSources();$('#modal').close();extensionStoresDialog(true);toast('Repositorio eliminado')}
async function refreshExtensionStores(){const button=$('[data-extension-stores-refresh]');if(button){button.disabled=true;button.classList.add('spinning')}const results=await Promise.allSettled(state.extensionStores.map(x=>api('/api/extension-store/inspect',{method:'POST',body:JSON.stringify({url:x.inputUrl||x.indexUrl})})));let updated=0;results.forEach((r,i)=>{if(r.status==='fulfilled'){state.extensionStores[i]=r.value;updated++}});persist();rebuildExtensionCatalog();renderExtensions();extensionStoresDialog(true);toast(updated===state.extensionStores.length?'Repositorios actualizados':`${updated}/${state.extensionStores.length} repositorios actualizados`)}
function copyExtensionStore(index){const item=state.extensionStores[index];if(!item)return;navigator.clipboard?.writeText?.(item.indexUrl);toast('URL del repositorio copiada')}
function openExtensionStore(index,kind='website'){const item=state.extensionStores[index],url=kind==='discord'?item?.discord:item?.website;try{const target=new URL(url);if(target.protocol!=='https:')throw new Error();window.open(target.href,'_blank','noopener')}catch{toast('Enlace externo no válido')}}
function handleExtensionStoreDeepLink(){const u=new URL(location.href),url=u.searchParams.get('extensionStore')||u.searchParams.get('addExtensionStore');if(!url)return;u.searchParams.delete('extensionStore');u.searchParams.delete('addExtensionStore');history.replaceState(history.state,'',u.pathname+u.search+u.hash);extensionStoresDialog();extensionStoreConfirmDialog(url)}

function sourcePreferencesScreen(id,restoring=false){const src=sourceById(id);if(!src)return;showBrowseChild('source-preferences',browseChildHead(src.name)+`<section class="browse-settings-list"><h3>Preferencias de la fuente</h3><p class="notice">Este adaptador web no expone preferencias configurables adicionales.</p><label class="browse-switch-row"><span><b>Fuente habilitada</b><small>Mostrar en Browse y búsquedas</small></span><input type="checkbox" data-bc-preference-enabled="${esc(id)}" ${state.disabled.has(id)?'':'checked'}></label></section>`,restoring,()=>sourcePreferencesScreen(id,true),{id})}
function migrationHelp(){modal(`<div class="dialog-section"><small class="eyebrow">GUÍA DE MIGRACIÓN</small><h3>Mover tu biblioteca</h3><ol><li>Selecciona la fuente que contiene las obras.</li><li>Marca una o varias obras.</li><li>Escoge otra fuente adjunta.</li><li>Hanami busca coincidencias por título.</li><li>Revisa y confirma cada resultado.</li></ol><p class="notice">La migración conserva el registro anterior. No borra capítulos ni realiza cambios en el sitio de origen.</p></div>`)}
function extRepo(ext){if(ext.repoUrl)return ext.repoUrl;if(ext.upstream?.startsWith('http'))return ext.upstream;return ext.upstream?`https://github.com/keiyoushi/extensions-source/tree/main/${ext.upstream}`:'https://github.com/keiyoushi/extensions-source'}
async function refreshExtensions(){const button=$('[data-refresh-extensions]');if(button){button.disabled=true;button.classList.add('spinning')};try{const e=await api('/api/extensions');const old=new Map(state.builtinExtensions.map(x=>[x.id,x]));state.builtinExtensions=(e.items||[]).map(x=>({...old.get(x.id),...x,sourceIds:x.sourceIds||old.get(x.id)?.sourceIds||[x.id]}));rebuildExtensionCatalog();renderExtensions();toast('Catálogo de extensiones actualizado')}catch(e){toast(e.message)}finally{if(button){button.disabled=false;button.classList.remove('spinning')}}}
async function confirmUninstall(id){const ext=state.extensions.find(x=>x.id===id);if(!ext)return;if(ext.external)await window.HanamiLocalExtensions.disable(id);const fromDetails=window.HanamiScreens?.current?.()?.type==='extension-details';extensionSourceIds(ext).forEach(x=>{state.installed.delete(x);state.disabled.delete(x);state.pinned.delete(x)});if(ext.external)state.sources=state.sources.filter(source=>!extensionSourceIds(ext).includes(source.id));delete state.installSteps[id];persist();rebuildExtensionCatalog();$('#modal').close();renderExtensions();renderSources();toast('Extensión desinstalada; biblioteca conservada');if(fromDetails)window.HanamiScreens?.back()}
async function updateExtension(id){const ext=state.extensions.find(x=>x.id===id);if(!ext)return;if(ext.external){state.installSteps[id]='Actualizando…';renderExtensions();try{await window.HanamiLocalExtensions.disable(id);await window.HanamiLocalExtensions.download(ext,ext.externalStore);delete state.installSteps[id];rebuildExtensionCatalog();renderExtensions();toast('Extensión local actualizada')}catch(error){delete state.installSteps[id];renderExtensions();toast(error.message)}return}state.installSteps[id]='Actualizando…';renderExtensions();setTimeout(()=>{delete state.installSteps[id];ext.hasUpdate=false;renderExtensions();toast('Extensión actualizada')},650)}
